/** A script that already runs the generator or its check, whatever runs the CLI (`ddd-ts-kit`, a wrapper script). */
const RUNS_SDK = /\bsdk\b/;

const BUILD = 'node node_modules/@typescript/native/bin/tsc -b clients';

/**
 * The scripts of a project whose contract has clients: `sdk:generate` and `sdk:build`, the
 * clients regenerated by `docs:generate` and compared by `docs:check` and `ci:docs`, and built by
 * `ci:build`, the step the build job of the pipeline runs. A script the team already made run
 * them is left as it is.
 */
export function sdkScripts(scripts: Readonly<Record<string, string>>): Record<string, string> {
  const extended = (name: string, step: string, pattern = RUNS_SDK): Record<string, string> => {
    const script = scripts[name];

    return script === undefined || pattern.test(script) ? {} : { [name]: `${script} && ${step}` };
  };

  return {
    ...scripts,
    'sdk:generate': scripts['sdk:generate'] ?? 'ddd-ts-kit sdk',
    'sdk:build': scripts['sdk:build'] ?? BUILD,
    ...extended('docs:generate', 'ddd-ts-kit sdk'),
    ...extended('docs:check', 'ddd-ts-kit sdk --check'),
    // A `ci:docs` that runs `docs:check` compares the clients through it.
    ...extended('ci:docs', 'ddd-ts-kit sdk --check', /\bsdk\b|docs:check/),
    ...extended('ci:build', 'npm run sdk:build', /\bsdk:build\b/),
  };
}
